begin;
create function private.assert_ok(v boolean,msg text) returns void language plpgsql as $$begin if v is distinct from true then raise exception 'FAIL: %',msg;end if;end$$;
select private.assert_ok((select count(*)=1 from annual_licenses where season_year=2026),'preserve full holders');
select private.assert_ok(public.has_full_license(1,2026) and not public.has_full_license(1,2027),'coverage year is explicit');
select private.assert_ok((public.player_license_eligibility(2,10)->>'temporary')::boolean and not (public.player_license_eligibility(2,11)->>'temporary')::boolean,'event licenses never cover another event');
set test.uid='00000000-0000-0000-0000-000000000001'; set test.email='admin@test.test'; set test.role='authenticated';
select manage_license('grant','{"player_id":1,"year":2027,"source":"complimentary","reason":"Renewal fixture"}');
select private.assert_ok((select status='upcoming' from private.license_register where player_id=1 and season_year=2027),'future license starts in January');
select private.assert_ok((select count(*)=1 from license_accounts where player_id=1),'number retained across renewal');
select manage_license('grant','{"player_id":3,"license_type":"temporary","event_id":10,"source":"manual","amount":120,"payment_method":"eft","reason":"Bank payment"}');
select private.assert_ok((select source='manual' from temporary_licenses where player_id=3),'manual temporary grant finalizes atomically');
select manage_license('grant','{"player_id":3,"year":2027,"source":"manual","amount":450,"payment_method":"cash","reason":"Annual cash payment"}');
select private.assert_ok((select license_type='temporary' from players where id=3),'future annual coverage does not start early');
select private.assert_ok((select count(*)=2 from payments),'only manual grants create revenue');
do $$begin begin perform manage_license('grant','{"player_id":3,"year":2027,"source":"manual","amount":450,"payment_method":"cash","reason":"Duplicate"}');raise exception 'duplicate grant accepted';exception when raise_exception then if sqlerrm='duplicate grant accepted' then raise;end if;end;end$$;
select private.assert_ok((select count(*)=2 from payments),'duplicate manual grant creates no extra payment');
select manage_license('revoke',jsonb_build_object('player_id',3,'id',(select id from annual_licenses where player_id=3 and season_year=2027),'reason','Revocation fixture'));
update payments set status='success' where player_id=3 and payment_type='full_license';
select private.assert_ok(not public.has_full_license(3,2027),'replayed callback must not restore revocation');
select manage_license('restore',jsonb_build_object('id',(select id from annual_licenses where player_id=3 and season_year=2027),'reason','Restore fixture'));
select private.assert_ok(public.has_full_license(3,2027),'explicit admin restore');
-- Refunds preserve event-license history and other coverage.
update temporary_licenses set revoked_at=now() where player_id=3;
select private.assert_ok((select count(*)=1 from temporary_licenses where player_id=3 and revoked_at is not null),'temporary history retained');
select private.assert_ok((select license_type='none' and not paid_registration from players where id=3),'revoked temp removes current coverage');
update players set license_type='full',paid_registration=true where id=3;
select private.assert_ok((select license_type='none' from players where id=3),'direct flag write cannot grant coverage');
select private.assert_ok((select count(*)>=7 from license_audit_log),'changes audited');
select private.assert_ok(((get_player_licenses(1)->>'license_number')='4M-000001'),'permanent number formatting');
-- A temporary license belongs to its player, even when another teammate has one for the same event.
select private.assert_ok((public.player_license_eligibility(2,10)->>'temporary')::boolean and not (public.player_license_eligibility(1,10)->>'temporary')::boolean,'a teammate temporary license cannot be shared');
select manage_license('grant','{"player_id":1,"license_type":"temporary","event_id":10,"source":"complimentary","reason":"Separate player event license fixture"}');
select private.assert_ok((select count(*)=3 from temporary_licenses where event_id=10),'separate players retain separate event records');
-- New yearless/unsnapshotted gateway charges never activate licenses.
insert into public.players values(4,'Payment fixture','payment@test.test','none',false);
insert into public.payments(player_id,amount,currency,status,payment_type,payment_method,reference,metadata) values(4,1,'ZAR','success','full_license','paystack','untrusted-year','{"license_year":2027,"license_type":"full"}');
select private.assert_ok(not public.has_full_license(4,2027),'a successful but unsnapshotted charge cannot mint coverage');
insert into public.native_license_checkouts(reference,user_id,player_id,amount,pricing,license_year,license_type) values('server-quote','00000000-0000-0000-0000-000000000001',4,450,'{}',2027,'full');
insert into public.payments(player_id,amount,currency,status,payment_type,payment_method,reference,metadata) values(4,450,'ZAR','success','membership','paystack','verified-charge','{"client_reference":"server-quote","license_type":"full"}');
select private.assert_ok(public.has_full_license(4,2027),'server checkout snapshot finalizes the correct season');
update public.payments set status='success' where reference='verified-charge';
select private.assert_ok((select count(*)=1 from public.annual_licenses where player_id=4 and season_year=2027),'webhook replay converges on one license');
select private.assert_ok(exists(select 1 from public.license_audit_log where player_id=4 and action='payment_review'),'ambiguous payment is visible for review');
-- Calls run as real authenticated role to test function guards and table privileges.
grant usage on schema auth to authenticated;
set session authorization authenticated;
set test.email='new@test.test';
select (get_player_licenses(3)->>'player_id')::bigint=3 as own_license_read;
do $$begin begin perform get_player_licenses(1);raise exception 'cross owner read accepted';exception when raise_exception then if sqlerrm='cross owner read accepted' then raise;end if;end;
begin perform manage_license('save_season','{"year":2027,"price":1,"sales_open":true,"reason":"Unauthorized"}');raise exception 'unauthorized change accepted';exception when raise_exception then if sqlerrm='unauthorized change accepted' then raise;end if;end;
begin update license_accounts set player_id=1 where player_id=3;raise exception 'number update accepted';exception when insufficient_privilege then null;end;
end$$;
reset session authorization;
set test.email='admin@test.test';
create or replace function public.license_today() returns date language sql stable set search_path='' as $$select '2027-01-01'::date$$;
select private.assert_ok((select status='expired' from private.license_register where player_id=1 and season_year=2026 and license_type='full'),'2026 expires at rollover');
select private.assert_ok((select status='active' from private.license_register where player_id=1 and season_year=2027),'2027 activates at rollover');
select refresh_license_projections();
select private.assert_ok((select license_type='full' from players where id=3),'rollover projects new Full license');
select private.assert_ok((select license_type='none' from players where id=2),'expired event license not retained');
select private.assert_ok(('2026-12-31 22:00:00Z'::timestamptz at time zone 'Africa/Johannesburg')::date='2027-01-01'::date,'SAST midnight boundary');
rollback;
